def seed_french(apps, schema_editor):
    Source = apps.get_model("site_content", "TranslationSource")
    Value = apps.get_model("site_content", "TranslationValue")
    for source_text, translated_text in FRENCH_TRANSLATIONS.items():
        source = Source.objects.filter(source_text=source_text, context="").first()
        if source is None:
            digest = hashlib.sha256(source_text.encode()).hexdigest()[:16]
            source = Source.objects.create(
                key=f"french.{digest}", source_text=source_text, context=""
            )
        Value.objects.update_or_create(
            source=source,
            language="fr",
            defaults={"translated_text": translated_text},
        )
        if source_text == COOKIE_TEXT_UK:
            for language, text in (("uk", COOKIE_TEXT_UK), ("de", COOKIE_TEXT_DE)):
                Value.objects.update_or_create(
                    source=source,
                    language=language,
                    defaults={"translated_text": text},
                )


def remove_french(apps, schema_editor):
    Value = apps.get_model("site_content", "TranslationValue")
    Value.objects.filter(language="fr").delete()


